import{_ as l,C as s,o as t,c as o,j as i,E as r,a as d,a2 as e}from"./chunks/framework.C21TwvGF.js";const q=JSON.parse(`{"title":"4-hafta","description":"","frontmatter":{"title":"4-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/8-sinf-cs/"},"n":4,"bob":"II-bob · Zamonaviy IT yo‘nalishlari va raqamli infratuzilma asoslari","lessons":[{"g":10,"title":"Internet qanday ishlaydi? IP, hosting, domen, DNS, brauzer, HTTP/HTTPS","lead":"Siz brauzerga manzil yozasiz va bir soniyada sahifa ochiladi. Bu orada IP, DNS, hosting va HTTPS qanday ishlaydi? Bugun internetning «ichki dunyosi»ga kiramiz.","link":"/8-sinf-cs/hafta-04/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-04/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-04/dars-1-test.html"},{"g":11,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (1-qism): bulutli saqlash, yuklash va ulashish","lead":"Telefoningiz yo'qolsa, undagi rasmlar ham yo'qoladimi? Agar ular «bulutda» bo'lsa — yo'q. Bugun bulut nima ekanini, fayllarni qanday yuklash va kimga qanday ruxsat bilan ulashishni o'rganamiz.","link":"/8-sinf-cs/hafta-04/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-04/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-04/dars-2-test.html"},{"g":12,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (2-qism): onlayn hujjatlar va vazifalarni boshqarish","lead":"To'rt kishi bitta taqdimotni qanday birga tayyorlaydi? Faylni bir-biriga 10 marta yuborib emas! Bugun bitta onlayn hujjatda birga yozamiz, izoh qoldiramiz va Trello doskasida vazifalarni bo'lishamiz.","link":"/8-sinf-cs/hafta-04/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-04/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-04/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"8-sinf-cs/hafta-04/index.md","filePath":"8-sinf-cs/hafta-04/index.md"}`),h={name:"8-sinf-cs/hafta-04/index.md"},u={class:"blk"},m={id:"uyga-vazifa",tabindex:"-1"};function g(y,a,f,b,c,z){const n=s("Icon");return t(),o("div",null,[i("div",u,[i("h2",m,[r(n,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=e('<p>Har bir vazifa 20–30 daqiqa vaqt oladi. Vazifalar daftarda yoki kompyuterda alohida papkada saqlanadi. Akkaunt kerak bo&#39;lgan qadamlarni ota-onangiz ruxsati va yordami bilan bajaring; akkaunt bo&#39;lmasa, shu qadamni daftarda chizma yoki jadval ko&#39;rinishida bajaring.</p><h3 id="_10-dars-uchun-internet-qanday-ishlaydi" tabindex="-1">10-dars uchun (Internet qanday ishlaydi?) <a class="header-anchor" href="#_10-dars-uchun-internet-qanday-ishlaydi" aria-label="Permalink to &quot;10-dars uchun (Internet qanday ishlaydi?)&quot;">​</a></h3><p><strong>1-topshiriq: «Internet yo&#39;li» mini-loyihasi</strong></p><ol><li>Sevimli saytingizni tanlang va uning to&#39;liq havolasini daftarga yozing.</li><li>Havolani bo&#39;laklarga ajrating: protokol, subdomen (bo&#39;lsa), domen nomi, zona, yo&#39;l.</li><li>Manzil <code>https://</code> bilan boshlanishini va qulf belgisi borligini tekshiring.</li><li>Sahifa ochilishining 5 bosqichini (siz → DNS → server → javob → brauzer) o&#39;z so&#39;zingiz bilan 5 jumlada yozing.</li></ol><p><strong>Kutiladigan natija:</strong> havolaning to&#39;g&#39;ri tahlili, HTTPS bo&#39;yicha xulosa va 5 bosqichli tushuntirish.</p><h3 id="_11-dars-uchun-bulutli-xizmatlar-1-qism" tabindex="-1">11-dars uchun (Bulutli xizmatlar, 1-qism) <a class="header-anchor" href="#_11-dars-uchun-bulutli-xizmatlar-1-qism" aria-label="Permalink to &quot;11-dars uchun (Bulutli xizmatlar, 1-qism)&quot;">​</a></h3><p><strong>2-topshiriq: «Mening bulutim»</strong></p><ol><li>Google Drive yoki OneDrive da (yoki daftarda daraxt ko&#39;rinishida) maktab fanlari bo&#39;yicha papka tuzilmasini yarating: kamida 3 ta fan papkasi, ulardan birida <code>4-hafta</code> ichki papkasi.</li><li>2 ta faylni (konspekt surati, referat yoki rasm) ma&#39;noli nom bilan joylang: <code>Fan_Mavzu_Familiya</code>.</li><li>Fayllardan birini ota-onangizga <strong>Ko&#39;ruvchi</strong> ruxsati bilan ulashing. Ruxsat sozlamasini ekran rasmiga oling yoki daftarga yozing.</li><li>3 jumla yozing: nega aynan shu ruxsatni tanladingiz va qaysi fayllarni hech qachon ochiq havola bilan ulashmaysiz.</li></ol><p><strong>Kutiladigan natija:</strong> tartibli papka tuzilmasi, to&#39;g&#39;ri nomlangan fayllar va asoslangan ruxsat tanlovi.</p><h3 id="_12-dars-uchun-bulutli-xizmatlar-2-qism" tabindex="-1">12-dars uchun (Bulutli xizmatlar, 2-qism) <a class="header-anchor" href="#_12-dars-uchun-bulutli-xizmatlar-2-qism" aria-label="Permalink to &quot;12-dars uchun (Bulutli xizmatlar, 2-qism)&quot;">​</a></h3><p><strong>3-topshiriq: «Oilaviy reja»</strong></p><ol><li>Trello da (yoki qog&#39;ozda 3 ustun chizib) «Dam olish kuni» doskasini yarating: <strong>Qilinadi</strong>, <strong>Jarayonda</strong>, <strong>Bajarildi</strong>.</li><li>Kamida 5 ta karta qo&#39;shing (masalan: xarid, tozalash, sayr, uy vazifasi, mehmon kutish), har biriga mas&#39;ul oila a&#39;zosi va muddat yozing.</li><li>Kun davomida kamida 3 ta kartani «Bajarildi» ustuniga o&#39;tkazing.</li><li>Google Docs (yoki Word onlayn) da 5 jumlali hisobot yozing: nima rejalashtirildi, nima bajarildi, nima qiyin bo&#39;ldi. Bitta oila a&#39;zosini <strong>Izohlovchi</strong> qilib qo&#39;shing va uning izohiga javob yozing.</li></ol><p><strong>Kutiladigan natija:</strong> 3 ustunli doska (kamida 5 karta), hisobot va kamida 1 ta izoh-javob.</p>',13))])])}const v=l(h,[["render",g]]);export{q as __pageData,v as default};
